/// Framer's gesture props on a `motion.div`: `whileHover`, `whileTap`, `whileFocus` and `whileInView` (with
/// `viewport`), their priority, the variant names a controlling component hands to the components in it, and
/// the callbacks. The midpoints are those of headless Chrome (`fixtures/gesture-oracle.json`, regenerated by
/// `fixtures/gesture-oracle.sh`): a width that moves linearly, and the Oklab mix a gpuix motion blends colours in.

import fs from "fs"
import path from "path"
import React, { useState } from "react"
import { fileURLToPath } from "url"
import { describe, expect, it } from "vitest"
import { AnimatePresence, motion } from "../index.js"
import { createTestRoot, hasNativeTestRenderer } from "../testing.js"
import { readLogicalPixels, SHOTS_DIR } from "./test-utils.js"

const describeNative = hasNativeTestRenderer ? describe : describe.skip

const ORACLE: { widthAtHalf: string; srgbRedBlueAtHalf: [number, number, number] } = JSON.parse(
  fs.readFileSync(path.resolve(path.dirname(fileURLToPath(import.meta.url)), "fixtures/gesture-oracle.json"), "utf8")
)

const LINEAR = { duration: 1, ease: "linear" } as const
const INSTANT = { duration: 0 } as const
const RED = "#ff0000"
const BLUE = "#0000ff"
const GREEN = "#00ff00"
const HALF_WIDTH = Number.parseFloat(ORACLE.widthAtHalf)

function setup(node: React.ReactNode, height = 200) {
  const testRoot = createTestRoot({ width: 400, height })
  const renderer = testRoot.renderer
  renderer.clockPause()
  const frame = (children: React.ReactNode) => (
    <div style={{ width: 400, height, backgroundColor: "#ffffff" }}>{children}</div>
  )
  testRoot.render(frame(node))
  let shots = 0
  const bounds = (testId: string) => {
    renderer.flush()
    return renderer.getElementBounds(renderer.findByTestId(testId)!.id)!
  }
  const page = {
    testRoot,
    renderer,
    rerender: (children: React.ReactNode) => testRoot.render(frame(children)),
    bounds,
    width: (testId: string) => bounds(testId).width,
    /** The pixel `dx`, `dy` from the top left corner of `testId`. */
    pixel: (testId: string, dx: number, dy: number) => {
      const file = `${SHOTS_DIR}/motion-gestures-${shots++}.png`
      renderer.captureScreenshot(file)
      const box = bounds(testId)
      return Array.from(readLogicalPixels(file, renderer).at(Math.floor(box.x + dx), Math.floor(box.y + dy)).slice(0, 3))
    },
    /** One frame, with the events it produced delivered. */
    advance: (ms: number) => {
      renderer.clockFastForward(ms)
      renderer.flush()
      renderer.dispatchNativeEvents()
    },
    inside: (testId: string) => {
      const box = bounds(testId)
      return [box.x + 4, box.y + 4] as const
    },
    hover: (testId: string) => renderer.nativeSimulateMouseMove(...page.inside(testId)),
    leave: () => renderer.nativeSimulateMouseMove(390, 190),
    press: (testId: string) => renderer.nativeSimulateMouseDown(...page.inside(testId)),
    release: (testId: string) => renderer.nativeSimulateMouseUp(...page.inside(testId)),
  }
  return page
}

function expectNear(actual: number[], expected: number[], tolerance = 3) {
  for (let i = 0; i < expected.length; i++) {
    expect(Math.abs(actual[i]! - expected[i]!), `${actual} vs ${expected}`).toBeLessThanOrEqual(tolerance)
  }
}

const box = { width: 100, height: 40 } as const

describeNative("whileHover on a motion.div", () => {
  it("moves a width and a colour to the target while the pointer is over it, and back", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={{ ...box, backgroundColor: RED }}
        whileHover={{ width: 200, backgroundColor: BLUE }}
        transition={LINEAR}
      />
    )
    expect(page.width("d")).toBe(100)
    page.hover("d")
    // The animation starts at the frame that sees the pointer there.
    page.advance(1)
    page.advance(499)
    expect(page.width("d")).toBeCloseTo(HALF_WIDTH, 0)
    expectNear(page.pixel("d", 20, 20), ORACLE.srgbRedBlueAtHalf)
    page.advance(500)
    expect(page.width("d")).toBeCloseTo(200, 0)
    expectNear(page.pixel("d", 20, 20), [0, 0, 255])

    page.leave()
    page.advance(1)
    page.advance(499)
    expect(page.width("d")).toBeCloseTo(HALF_WIDTH, 0)
    page.advance(500)
    expect(page.width("d")).toBeCloseTo(100, 0)
    expectNear(page.pixel("d", 20, 20), [255, 0, 0])
    page.testRoot.unmount()
  })

  it("returns a property to the animate value, not the style, when animate sets it", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={{ ...box }}
        animate={{ width: 140 }}
        whileHover={{ width: 200 }}
        transition={INSTANT}
      />
    )
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(140, 0)
    page.hover("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.leave()
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(140, 0)
    page.testRoot.unmount()
  })

  it("plays the transition of its own target", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        whileHover={{ width: 200, transition: { duration: 4, ease: "linear" } }}
        transition={LINEAR}
      />
    )
    page.hover("d")
    page.advance(1)
    page.advance(1000)
    expect(page.width("d")).toBeCloseTo(125, 0)
    page.testRoot.unmount()
  })

  it("is on while the pointer is over a child of it", () => {
    const page = setup(
      <motion.div testId="d" style={{ ...box, width: 200 }} whileHover={{ height: 80 }} transition={INSTANT}>
        <div testId="c" style={{ width: 50, height: 20 }} />
      </motion.div>
    )
    page.hover("c")
    page.advance(10)
    expect(page.bounds("d").height).toBeCloseTo(80, 0)
    page.leave()
    page.advance(10)
    expect(page.bounds("d").height).toBeCloseTo(40, 0)
    page.testRoot.unmount()
  })

  it("answers to none of them on a node that is leaving AnimatePresence", () => {
    function Show({ show }: { show: boolean }) {
      return (
        <AnimatePresence>
          {show ? (
            <motion.div
              key="d"
              testId="d"
              style={box}
              whileHover={{ width: 200 }}
              exit={{ opacity: 0.5 }}
              transition={{ default: { duration: 10, ease: "linear" }, width: INSTANT }}
            />
          ) : null}
        </AnimatePresence>
      )
    }
    const page = setup(<Show show />)
    page.hover("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.rerender(<Show show={false} />)
    page.advance(10)
    // Leaving, the node goes on with its exit and the hover target is let go of.
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })
})

describeNative("whileTap on a motion.div", () => {
  it("is on from the press to the release, wherever the pointer is released", () => {
    const page = setup(<motion.div testId="d" style={box} whileTap={{ width: 200 }} transition={INSTANT} />)
    page.hover("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.press("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.release("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)

    page.press("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.renderer.nativeSimulateMouseMove(390, 190)
    page.renderer.nativeSimulateMouseUp(390, 190)
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("wins over whileHover while both are on, and lets it back in after the release", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        whileHover={{ width: 150, height: 60 }}
        whileTap={{ width: 200 }}
        transition={INSTANT}
      />
    )
    page.hover("d")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 150, height: 60 })
    page.press("d")
    page.advance(10)
    // The tap wins the width it shares; the hover still holds the height.
    expect(page.bounds("d")).toMatchObject({ width: 200, height: 60 })
    page.release("d")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 150, height: 60 })
    page.testRoot.unmount()
  })
})

describeNative("whileFocus on a motion.div", () => {
  it("is on while the element has focus that :focus-visible matches, as in Framer", () => {
    const page = setup(
      <>
        <motion.div testId="d" tabIndex={0} style={box} whileFocus={{ width: 200 }} transition={INSTANT} />
        <div testId="other" tabIndex={0} style={box} />
      </>
    )
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("is not on for a focus a mouse press gave it", () => {
    const page = setup(<motion.div testId="d" tabIndex={0} style={box} whileFocus={{ width: 200 }} transition={INSTANT} />)
    page.press("d")
    page.release("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("is under whileHover and whileTap, as Framer orders animate, whileInView, whileFocus, whileHover, whileTap", () => {
    const page = setup(
      <>
        <motion.div
          testId="d"
          tabIndex={0}
          style={box}
          whileHover={{ width: 150 }}
          whileTap={{ width: 160 }}
          whileFocus={{ width: 200, height: 70 }}
          transition={INSTANT}
        />
        <div tabIndex={0} style={box} />
      </>
    )
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 200, height: 70 })
    page.hover("d")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 150, height: 70 })
    page.press("d")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 160, height: 70 })
    page.release("d")
    page.leave()
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 200, height: 70 })
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.bounds("d")).toMatchObject({ width: 100, height: 40 })
    page.testRoot.unmount()
  })
})

describeNative("whileInView on a motion.div", () => {
  function scene(spacer: number, extra: Record<string, unknown> = {}, height = 100) {
    return (
      <div style={{ width: 400, height: 200 }}>
        <div style={{ height: spacer }} />
        <motion.div
          testId="d"
          style={{ width: 100, height }}
          whileInView={{ width: 200 }}
          transition={INSTANT}
          {...extra}
        />
      </div>
    )
  }

  function observe(extra: Record<string, unknown> = {}, height = 100) {
    const testRoot = createTestRoot({ width: 400, height: 200 })
    const renderer = testRoot.renderer
    renderer.clockPause()
    testRoot.render(scene(600, extra, height))
    const width = () => {
      renderer.flush()
      return renderer.getElementBounds(renderer.findByTestId("d")!.id)!.width
    }
    const settle = () => {
      for (let step = 0; step < 8; step++) {
        renderer.clockFastForward(20)
        renderer.flush()
        renderer.dispatchNativeEvents()
      }
    }
    return { testRoot, width, settle, show: (spacer: number) => testRoot.render(scene(spacer, extra, height)) }
  }

  it("is on while any of it shows, and off when it does not", () => {
    const page = observe()
    page.settle()
    expect(page.width()).toBe(100)
    page.show(0)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.show(600)
    page.settle()
    expect(page.width()).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("stays on with viewport.once", () => {
    const page = observe({ viewport: { once: true } })
    page.show(0)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.show(600)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.testRoot.unmount()
  })

  it("waits for viewport.amount of it to show", () => {
    const page = observe({ viewport: { amount: 0.5 } })
    // 40px of the 100px show: under half.
    page.show(160)
    page.settle()
    expect(page.width()).toBe(100)
    // 60px show.
    page.show(140)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.testRoot.unmount()
  })

  it("waits for all of it with amount all", () => {
    const page = observe({ viewport: { amount: "all" } })
    page.show(150)
    page.settle()
    expect(page.width()).toBe(100)
    page.show(100)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.testRoot.unmount()
  })

  it("takes viewport.margin as the margin of the viewport", () => {
    const page = observe({ viewport: { margin: "0px 0px 200px 0px" } })
    // 300px below the bottom edge, but the margin grows the viewport by 200px.
    page.show(250)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.show(450)
    page.settle()
    expect(page.width()).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("is lower than whileHover", () => {
    const page = observe({ whileHover: { width: 150 } })
    page.show(0)
    page.settle()
    expect(page.width()).toBeCloseTo(200, 0)
    page.testRoot.unmount()
  })
})

describeNative("variants by name", () => {
  const variants = {
    rest: { width: 100, backgroundColor: RED },
    hover: { width: 200, backgroundColor: BLUE },
    press: { width: 160 },
  }
  const childVariants = {
    rest: { height: 40 },
    hover: { height: 80 },
    press: { height: 60 },
  }

  it("takes a gesture target by variant name", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={{ height: 40 }}
        variants={variants}
        initial="rest"
        animate="rest"
        whileHover="hover"
        whileTap="press"
        transition={INSTANT}
      />
    )
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.hover("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.press("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(160, 0)
    page.release("d")
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(200, 0)
    page.leave()
    page.advance(10)
    expect(page.width("d")).toBeCloseTo(100, 0)
    page.testRoot.unmount()
  })

  it("hands the names of whileHover and whileTap down to the components with variants in it", () => {
    const page = setup(
      <motion.div
        testId="parent"
        style={{ width: 200, height: 100 }}
        initial="rest"
        animate="rest"
        whileHover="hover"
        whileTap="press"
        variants={{ rest: {}, hover: {}, press: {} }}
        transition={INSTANT}
      >
        <div style={{ height: 10 }} />
        <motion.div testId="child" style={{ width: 20 }} variants={childVariants} transition={INSTANT}>
          <motion.div testId="grandchild" style={{ width: 10 }} variants={{ hover: { width: 70 } }} transition={INSTANT} />
        </motion.div>
      </motion.div>
    )
    // Without animate or initial of its own, the child starts at the parent's names.
    expect(page.bounds("child").height).toBeCloseTo(40, 0)
    // The parent is hovered through its child: the pointer is over the parent, not over the child's own box.
    page.renderer.nativeSimulateMouseMove(...page.inside("parent"))
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(80, 0)
    // A name the grandchild defines goes down through a child that does not define it as well.
    expect(page.width("grandchild")).toBeCloseTo(70, 0)
    page.renderer.nativeSimulateMouseDown(...page.inside("parent"))
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(60, 0)
    // The grandchild has no "press"; it keeps the hover it was given, which the press did not take from the parent.
    page.renderer.nativeSimulateMouseUp(...page.inside("parent"))
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(80, 0)
    page.leave()
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(40, 0)
    expect(page.width("grandchild")).toBeCloseTo(10, 0)
    page.testRoot.unmount()
  })

  it("hands the name of animate down, and follows it as it changes", () => {
    function Scene() {
      const [open, setOpen] = useState(false)
      return (
        <motion.div
          testId="parent"
          style={{ width: 200, height: 100 }}
          initial="closed"
          animate={open ? "open" : "closed"}
          onClick={() => setOpen(!open)}
          transition={INSTANT}
        >
          <motion.div
            testId="child"
            style={{ width: 20 }}
            variants={{ closed: { height: 10 }, open: { height: 70 } }}
            transition={INSTANT}
          />
        </motion.div>
      )
    }
    const page = setup(<Scene />)
    const click = () => {
      page.press("parent")
      page.release("parent")
    }
    expect(page.bounds("child").height).toBeCloseTo(10, 0)
    click()
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(70, 0)
    click()
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(10, 0)
    page.testRoot.unmount()
  })

  it("lets the props of a component that names variants itself break the chain", () => {
    const page = setup(
      <motion.div
        testId="parent"
        style={{ width: 200, height: 100 }}
        initial="rest"
        animate="rest"
        whileHover="hover"
        variants={{ rest: {}, hover: {} }}
        transition={INSTANT}
      >
        <div style={{ height: 10 }} />
        <motion.div testId="own" animate="rest" variants={childVariants} style={{ width: 20 }} transition={INSTANT} />
        <motion.div testId="object" animate={{ height: 30 }} variants={childVariants} style={{ width: 20 }} transition={INSTANT} />
      </motion.div>
    )
    page.renderer.nativeSimulateMouseMove(...page.inside("parent"))
    page.advance(10)
    // The first names variants of its own (rest) and ignores the hover; the second animates an object,
    // which does not make it a controller, so the hover still reaches it.
    expect(page.bounds("own").height).toBeCloseTo(40, 0)
    expect(page.bounds("object").height).toBeCloseTo(80, 0)
    page.leave()
    page.advance(10)
    expect(page.bounds("object").height).toBeCloseTo(30, 0)
    page.testRoot.unmount()
  })

  it("lets a gesture of its own win over the name handed down", () => {
    const page = setup(
      <motion.div
        testId="parent"
        style={{ width: 200, height: 100 }}
        animate="rest"
        whileHover="hover"
        variants={{ rest: {}, hover: {} }}
        transition={INSTANT}
      >
        <div style={{ height: 10 }} />
        <motion.div
          testId="child"
          style={{ width: 20 }}
          variants={childVariants}
          whileHover={{ height: 15 }}
          transition={INSTANT}
        />
      </motion.div>
    )
    page.renderer.nativeSimulateMouseMove(...page.inside("parent"))
    page.advance(10)
    // The pointer is over the parent and not the child: the child's own target is not on.
    expect(page.bounds("child").height).toBeCloseTo(40, 0)
    page.renderer.nativeSimulateMouseMove(...page.inside("child"))
    page.advance(10)
    expect(page.bounds("child").height).toBeCloseTo(15, 0)
    page.testRoot.unmount()
  })

  it("throws for a name the component writes that its variants do not define", () => {
    const errors: unknown[] = []
    const testRoot = createTestRoot({ onUncaughtError: (error) => errors.push(error) })
    try {
      testRoot.render(<motion.div variants={{ rest: {} }} whileHover="nope" />)
    } catch (error) {
      errors.push(error)
    }
    testRoot.unmount()
    expect(errors).toHaveLength(1)
    expect((errors[0] as Error).message).toContain('names the variant "nope"')
  })

  it("passes the name of whileInView down", () => {
    function scene(spacer: number) {
      return (
        <div style={{ width: 400, height: 200 }}>
          <div style={{ height: spacer }} />
          <motion.div
            style={{ width: 100, height: 100 }}
            whileInView="seen"
            variants={{ seen: {} }}
            transition={INSTANT}
          >
            <motion.div testId="child" style={{ width: 10 }} variants={{ seen: { width: 90 } }} transition={INSTANT} />
          </motion.div>
        </div>
      )
    }
    const testRoot = createTestRoot({ width: 400, height: 200 })
    const renderer = testRoot.renderer
    renderer.clockPause()
    testRoot.render(scene(600))
    const settle = () => {
      for (let step = 0; step < 8; step++) {
        renderer.clockFastForward(20)
        renderer.flush()
        renderer.dispatchNativeEvents()
      }
    }
    const width = () => {
      renderer.flush()
      return renderer.getElementBounds(renderer.findByTestId("child")!.id)!.width
    }
    settle()
    expect(width()).toBe(10)
    testRoot.render(scene(0))
    settle()
    expect(width()).toBeCloseTo(90, 0)
    testRoot.unmount()
  })
})

describeNative("gesture callbacks", () => {
  it("calls onHoverStart and onHoverEnd as the pointer enters and leaves, with its position", () => {
    const calls: string[] = []
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        onHoverStart={(_event, info) => calls.push(`start ${info.point.x},${info.point.y}`)}
        onHoverEnd={() => calls.push("end")}
      />
    )
    const [x, y] = page.inside("d")
    page.renderer.nativeSimulateMouseMove(x, y)
    page.advance(10)
    expect(calls).toEqual([`start ${x},${y}`])
    page.leave()
    page.advance(10)
    expect(calls.slice(1)).toEqual(["end"])
    page.testRoot.unmount()
  })

  it("calls onTapStart on the press and onTap on a release over the element", () => {
    const calls: string[] = []
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        onTapStart={() => calls.push("start")}
        onTap={() => calls.push("tap")}
        onTapCancel={() => calls.push("cancel")}
      />
    )
    page.press("d")
    page.advance(10)
    expect(calls).toEqual(["start"])
    page.release("d")
    page.advance(10)
    expect(calls).toEqual(["start", "tap"])
    page.testRoot.unmount()
  })

  it("calls onTapCancel for a release elsewhere", () => {
    const calls: string[] = []
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        onTapStart={() => calls.push("start")}
        onTap={() => calls.push("tap")}
        onTapCancel={() => calls.push("cancel")}
      />
    )
    page.press("d")
    page.renderer.nativeSimulateMouseMove(390, 190)
    page.renderer.nativeSimulateMouseUp(390, 190)
    page.advance(10)
    expect(calls).toEqual(["start", "cancel"])
    page.testRoot.unmount()
  })

  it("leaves the pointer handlers of the app alone", () => {
    const calls: string[] = []
    const page = setup(
      <motion.div
        testId="d"
        style={box}
        onPointerEnter={() => calls.push("enter")}
        onPointerDown={() => calls.push("down")}
        onHoverStart={() => calls.push("hover")}
        onTapStart={() => calls.push("tap")}
      />
    )
    page.hover("d")
    page.press("d")
    page.advance(10)
    expect(calls).toEqual(["hover", "enter", "down", "tap"])
    page.testRoot.unmount()
  })

  it("calls the hover and tap callbacks of a motion.span", () => {
    const calls: string[] = []
    const page = setup(
      <text testId="p" style={{ fontSize: 16, lineHeight: "20px", fontFamily: "Menlo", color: "#000000" }}>
        <motion.span
          testId="s"
          onHoverStart={() => calls.push("hover")}
          onHoverEnd={() => calls.push("unhover")}
          onTap={() => calls.push("tap")}
        >
          aaaa
        </motion.span>
      </text>
    )
    page.hover("s")
    page.press("s")
    page.release("s")
    page.leave()
    page.advance(10)
    expect(calls).toEqual(["hover", "tap", "unhover"])
    page.testRoot.unmount()
  })

  it("calls onViewportEnter and onViewportLeave", () => {
    const calls: string[] = []
    const scene = (spacer: number) => (
      <div style={{ width: 400, height: 200 }}>
        <div style={{ height: spacer }} />
        <motion.div
          style={box}
          onViewportEnter={() => calls.push("enter")}
          onViewportLeave={() => calls.push("leave")}
        />
      </div>
    )
    const testRoot = createTestRoot({ width: 400, height: 200 })
    const renderer = testRoot.renderer
    renderer.clockPause()
    testRoot.render(scene(600))
    const settle = () => {
      for (let step = 0; step < 8; step++) {
        renderer.clockFastForward(20)
        renderer.flush()
        renderer.dispatchNativeEvents()
      }
    }
    settle()
    expect(calls).toEqual([])
    testRoot.render(scene(0))
    settle()
    expect(calls).toEqual(["enter"])
    testRoot.render(scene(600))
    settle()
    expect(calls).toEqual(["enter", "leave"])
    testRoot.unmount()
  })
})

describeNative("gestures on the other motion components", () => {
  it("takes whileHover on a motion.path through the variant name of a component above it", () => {
    const page = setup(
      <motion.div
        testId="d"
        style={{ width: 100, height: 100 }}
        whileHover="on"
        variants={{ off: {}, on: {} }}
        transition={INSTANT}
      >
        <svg width={100} height={100} viewBox="0 0 100 100">
          <motion.path
            d="M0 50 L100 50"
            stroke={RED}
            strokeWidth={20}
            variants={{ on: { stroke: GREEN } }}
            transition={INSTANT}
          />
        </svg>
      </motion.div>
    )
    expectNear(page.pixel("d", 50, 50), [255, 0, 0])
    page.hover("d")
    page.advance(10)
    expectNear(page.pixel("d", 50, 50), [0, 255, 0])
    page.leave()
    page.advance(10)
    expectNear(page.pixel("d", 50, 50), [255, 0, 0])
    page.testRoot.unmount()
  })
})
